import{_ as t,a,c as n,ac as i}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"第四册：流利英语 · Lesson 47 The great escape","description":"学习 篇章指代与 this + 概括名词，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第四册：流利英语 · Lesson 47 The great escape","description":"学习 篇章指代与 this + 概括名词，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第4册课时","summary":"学习 篇章指代与 this + 概括名词，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第四册：流利英语 · Lesson 46 Hobbies","link":"/life/english/new-concept/book-4/unit-06/lesson-046"},"next":{"text":"第四册：流利英语 · Lesson 48 Planning a share portfolio","link":"/life/english/new-concept/book-4/unit-06/lesson-048"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第四册：流利英语 · Lesson 46 Hobbies","link":"/life/english/new-concept/book-4/unit-06/lesson-046"},"next":{"text":"第四册：流利英语 · Lesson 48 Planning a share portfolio","link":"/life/english/new-concept/book-4/unit-06/lesson-048"}},"headers":[],"relativePath":"life/english/new-concept/book-4/unit-06/lesson-047.md","filePath":"life/english/new-concept/book-4/unit-06/lesson-047.md"}'),o={name:"life/english/new-concept/book-4/unit-06/lesson-047.md"};function s(r,e,l,h,c,d){return a(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="第四册-流利英语-·-lesson-47-the-great-escape" tabindex="-1">第四册：流利英语 · Lesson 47 The great escape <a class="header-anchor" href="#第四册-流利英语-·-lesson-47-the-great-escape" aria-label="Permalink to &quot;第四册：流利英语 · Lesson 47 The great escape&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-4/contents">本册目录</a> · <a href="/life/english/new-concept/book-4/unit-06/overview">单元 6</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>本课从露营度假中的经济动机、生活方式和社交感受讨论“逃离日常”，而非讲述具体越狱。阅读时留意便宜并非唯一动机，装备与自由之间也可能形成反差。重点用 this、that 加概括名词串联观点，准确指明作者在回应哪一种期待，避免把个别旅行感受推广到所有游客。</p><p>本课以主题阅读带动语言分析，学习重点如下。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>escape</td><td>/ɪˈskeɪp/</td><td>n.</td><td>逃离；解脱</td><td>an escape from routine</td></tr><tr><td>routine</td><td>/ruːˈtiːn/</td><td>n.</td><td>惯常生活</td><td>daily routine</td></tr><tr><td>expectation</td><td>/ˌekspekˈteɪʃən/</td><td>n.</td><td>期待</td><td>an unrealistic expectation</td></tr><tr><td>contrast</td><td>/ˈkɒntrɑːst/</td><td>n.</td><td>对比</td><td>a sharp contrast</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>get away from — 暂时离开某环境</li><li>live up to — 达到某种期待</li></ul><h2 id="语法讲解-篇章指代与-this-概括名词" tabindex="-1">语法讲解：篇章指代与 this + 概括名词 <a class="header-anchor" href="#语法讲解-篇章指代与-this-概括名词" aria-label="Permalink to &quot;语法讲解：篇章指代与 this + 概括名词&quot;">​</a></h2><p>this/that 可以指前一句或前一段的整体意思，但裸用 This is important 常让读者不知指代对象。使用 this expectation、that assumption、such a contrast 等概括名词，可把关系说清楚。概括名词本身也包含解释，不能随意把前句的“可能”称为 this fact。指代不应跨越太多竞争对象；若有两个可指对象，重复关键名词往往比继续用代词更清晰。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>We expected the trip to remove every worry. That expectation proved unrealistic.</p></blockquote><p>我们原以为旅行能消除所有烦恼。事实证明，这一期待不切实际。</p><p>That expectation 概括前句内容，明确指向“旅行消除所有烦恼”的想法，而非 trip 本身。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>前句只是猜测时，后句不能随意称 this fact；应使用 this possibility 或 this assumption。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>读 That expectation 时稍重读 expectation；回听后用一句中文说明它回指什么，检查篇章关系。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>I expected camping to be no more than a cheaper holiday. Sharing a table with strangers changed my view. That experience made conversation, rather than cost alone, the most memorable part of the trip.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>写三句露营反思：出发前期待、实际体验、用概括名词连接认识。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>露营场景呼应本课主题；That experience 明确回指与陌生人同桌交流，比较结构说明动机和收获不止费用。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>示例中的 That expectation 指什么？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 旅行能消除所有烦恼的期待。</p><p><strong>解析：</strong> 概括名词回指前句整项想法。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>“It may rain.” 后应接 this possibility 还是 this fact？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> this possibility</p><p><strong>解析：</strong> may rain 表可能而非已确认事实。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>改进含糊指代：We changed the route and cancelled the hotel. This cost money.（指取消酒店）</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> We changed the route and cancelled the hotel. The cancellation cost money.</p><p><strong>解析：</strong> 明确重复 cancellation，消除两个动作间的歧义。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：篇章指代与 this + 概括名词。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-4/unit-06/grammar">单元语法</a> · <a href="/life/english/new-concept/book-4/unit-06/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-4/unit-06/review">单元自测</a></p><p><a href="/life/english/new-concept/book-4/unit-06/lesson-046">上一课</a> · <a href="/life/english/new-concept/book-4/unit-06/overview">单元目录</a> · <a href="/life/english/new-concept/book-4/unit-06/lesson-048">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const b=t(o,[["render",s]]);export{u as __pageData,b as default};
